/**
 * Offline real Stripe SDK -> loopback-only HTTP webhook harness.
 * The webhook signature is generated by the official SDK. No external Stripe
 * API, real payment, public listener, Replit, or persistent database.
 */
import assert from "node:assert/strict";
import Stripe from "stripe";
import { createIsolatedSandboxWebhookServer } from "../src/isolated-sandbox-webhook.mjs";
import { createPreviewServer } from "../src/server.mjs";

const stripe=new Stripe("sk_test_offline_fixture_only",{apiVersion:"2025-02-24.acacia"});
const endpointSecret="whsec_http_offline_fixture_only";
const order={
  id:"order1",userId:"synthetic_member",stripeSessionId:"cs_test_HttpSdk123",
  status:"pending",amountMinor:4900,currency:"usd",
  consultationKey:"quick",configuredPriceId:"price_Offline123"
};
const event={
  id:"evt_HttpSdk123",livemode:false,type:"checkout.session.completed",
  data:{object:{
    id:order.stripeSessionId,livemode:false,mode:"payment",
    payment_status:"paid",client_reference_id:order.userId,
    amount_total:4900,currency:"usd",
    metadata:{orderId:order.id,consultationKey:"quick"}
  }}
};
const body=JSON.stringify(event);
const sign=raw=>stripe.webhooks.generateTestHeaderString({payload:raw,secret:endpointSecret});
const signature=sign(body);
let events=0,entitlements=0,providerLookups=0,transactions=0,outage=false;
stripe.checkout.sessions.listLineItems=async()=>{
  providerLookups++;
  if(outage)throw Error("offline_provider_unavailable");
  return {has_more:false,data:[{
    quantity:1,amount_total:4900,
    price:{id:order.configuredPriceId,active:true,currency:"usd"}
  }]};
};
const repository={
  findOrderBySession:async id=>id===order.stripeSessionId?{...order}:null,
  transaction:async fn=>{
    transactions++;
    return fn({
      lockOrderBySession:async()=>({...order}),
      recordEventOnce:async()=>{if(events)return false;events++;return true;},
      applyDecision:async decision=>{
        if(decision.action!=="mark_paid")throw Error("unexpected_decision");
        entitlements++;
        order.status="paid";
      }
    });
  }
};
// For replay semantics a paid order should still deduplicate via event ID.
const server=createIsolatedSandboxWebhookServer({stripe,repository,endpointSecret});
await new Promise((resolve,reject)=>{server.once("error",reject);server.listen(0,"127.0.0.1",resolve);});
const host="http://127.0.0.1:"+server.address().port;
const post=(raw,sig)=>fetch(host+"/sandbox/webhook",{
  method:"POST",headers:{"stripe-signature":sig},body:raw
});
try{
  assert.equal(server.address().address,"127.0.0.1");
  // Signature tampering must not invoke provider or repository writes.
  const tampered=await post(body+" ",signature);
  assert.equal(tampered.status,400);
  assert.equal(providerLookups,0);
  assert.equal(events,0);

  // A signed event with temporary provider outage must remain retryable.
  outage=true;
  const unavailable=await post(body,signature);
  assert.equal(unavailable.status,503);
  assert.equal(events,0);
  assert.equal(entitlements,0);

  outage=false;
  const paid=await post(body,signature);
  assert.equal(paid.status,200);
  assert.equal((await paid.json()).action,"mark_paid");
  assert.equal(events,1);
  assert.equal(entitlements,1);
  assert.equal(order.status,"paid");

  const replay=await post(body,signature);
  assert.equal(replay.status,200);
  assert.equal((await replay.json()).action,"duplicate");
  assert.equal(events,1);
  assert.equal(entitlements,1);
  assert.ok(providerLookups>=3);
  assert.equal(transactions,2);

  // An unrelated or disabled public Checkout endpoint must not be created.
  const hidden=await fetch(host+"/api/checkout");
  assert.equal(hidden.status,404);
  const preview=createPreviewServer();
  await new Promise(resolve=>preview.listen(0,"127.0.0.1",resolve));
  try{
    const r=await fetch("http://127.0.0.1:"+preview.address().port+"/api/checkout",{method:"POST"});
    assert.equal(r.status,503);
  } finally {
    await new Promise(resolve=>preview.close(resolve));
  }
  console.log("PASS: official Stripe SDK signed event traverses isolated loopback HTTP server, retries after outage, deduplicates and leaves preview Checkout blocked");
}finally{
  await new Promise(resolve=>server.close(resolve));
}
